  const b=x*vx,disc=b*b-travel*travel*c;if(travel<=1e-8||b>=0||disc<0)return Infinity;
  const t=(-b-Math.sqrt(disc))/(travel*travel);return t>=0&&t<=1?t:Infinity;};
